// local harness: build Page.tsx, dump geometry of figure elements, screenshot
import fs from "node:fs"
import path from "node:path"
import http from "node:http"
import { build } from "vite"
import react from "@vitejs/plugin-react"
import tailwindcss from "@tailwindcss/vite"
import { chromium } from "playwright-core"
import { createRequire } from "node:module"

const require = createRequire(import.meta.url)
const UI = "/home/user/QFY1012.github.io/experiments/ui-loop"
const ws = path.resolve(".")
const APP = path.join(UI, "app")
const OUT = path.join(ws, ".m-build")

await build({
  root: APP,
  base: "./",
  logLevel: "error",
  configFile: false,
  plugins: [
    { name: "workspace-source", enforce: "pre", transform: (code, id) => (id.endsWith("/src/index.css") ? `${code}\n@source "${ws}/Page.tsx";\n` : null) },
    react(),
    tailwindcss(),
  ],
  resolve: {
    alias: [
      { find: "@page", replacement: path.join(ws, "Page.tsx") },
      { find: /^react\/jsx-runtime$/, replacement: require.resolve("react/jsx-runtime") },
      { find: /^react$/, replacement: require.resolve("react") },
      { find: "@", replacement: path.join(APP, "src") },
    ],
  },
  build: { outDir: OUT, emptyOutDir: true, chunkSizeWarningLimit: 8000 },
})
if (fs.existsSync(path.join(ws, "assets"))) fs.cpSync(path.join(ws, "assets"), path.join(OUT, "assets"), { recursive: true })

const MIME = { ".png": "image/png", ".js": "text/javascript", ".css": "text/css", ".html": "text/html", ".woff2": "font/woff2", ".json": "application/json" }
const server = http.createServer((req, res) => {
  const p = path.join(OUT, decodeURIComponent(new URL(req.url, "http://x").pathname))
  if (!p.startsWith(OUT) || !fs.existsSync(p) || fs.statSync(p).isDirectory()) return res.writeHead(404).end()
  res.writeHead(200, { "content-type": MIME[path.extname(p)] ?? "application/octet-stream" })
  fs.createReadStream(p).pipe(res)
})
await new Promise((r) => server.listen(0, "127.0.0.1", r))
const browser = await chromium.launch({ executablePath: process.env.CHROMIUM_PATH ?? "/opt/pw-browsers/chromium" })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 })
await page.goto(`http://127.0.0.1:${server.address().port}/index.html`)
await page.waitForFunction(() => window.__READY__ === true, null, { timeout: 30000 })
const info = await page.evaluate(() => {
  const main = document.querySelector("main")
  const mr = main.getBoundingClientRect()
  const rows = [...document.querySelectorAll("[data-slot=figure-strip],[data-slot=figure-grid],[data-slot=figure-compare]")].map((r) => ({
    slot: r.getAttribute("data-slot"),
    w: Math.round(r.getBoundingClientRect().width),
    figs: [...r.querySelectorAll("[data-slot=figure]")].map((f) => {
      const i = f.querySelector("[data-slot=figure-image]")
      const r2 = i.getBoundingClientRect()
      return `${Math.round(r2.width)}x${Math.round(r2.height)}@${Math.round(r2.left - mr.left)}`
    }),
  }))
  return { mainLeft: Math.round(mr.left), mainW: Math.round(mr.width), rows }
})
console.log(JSON.stringify(info, null, 1))
const h = await page.evaluate(() => Math.ceil(document.documentElement.scrollHeight))
await page.screenshot({ path: path.join(ws, "probe.png"), clip: { x: (1440 - 1152) / 2 - 48, y: 0, width: 1152 + 96, height: Math.min(h, 1400) }, fullPage: true })
await browser.close()
server.close()

